package glitch

import data.glitch_lib

http_protocol_names := {"listener_protocol", "backend_protocol", "target_protocol", "frontend_protocol", "protocol", "scheme"}

ssl_disable_names := {"ssl_enabled", "enable_https", "require_ssl"}

is_http_protocol(value) {
    value.ir_type == "String"
    upper(value.value) == "HTTP"
}

is_http_url(value) {
    value.ir_type == "String"
    startswith(lower(value.value), "http://")
}

# Detect http:// URLs in attribute values
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]
    is_http_url(attr.value)
    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Use of HTTP without SSL/TLS - Plaintext HTTP URL detected in configuration. (CWE-319)"
    }
}

# Detect protocol attributes explicitly set to HTTP
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]
    attr.name == http_protocol_names[_]
    is_http_protocol(attr.value)
    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Use of HTTP without SSL/TLS - Protocol is configured as HTTP instead of HTTPS. (CWE-319)"
    }
}

# Detect insecure: true
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]
    attr.name == "insecure"
    attr.value.ir_type == "Boolean"
    attr.value.value == true
    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Use of HTTP without SSL/TLS - Insecure flag is explicitly set to true, bypassing TLS. (CWE-319)"
    }
}

# Detect SSL/TLS explicitly disabled via boolean false flags
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]
    attr.name == ssl_disable_names[_]
    attr.value.ir_type == "Boolean"
    attr.value.value == false
    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Use of HTTP without SSL/TLS - SSL/TLS is explicitly disabled in configuration. (CWE-319)"
    }
}

